-- Expose verified CP hooks; every gameplay mutation is namespaced and owner-scoped.
UPDATE CustomModOptions SET Value=1 WHERE Name IN
 ('EVENTS_BATTLES','EVENTS_UNIT_PREKILL','EVENTS_UNIT_CREATED','EVENTS_UNIT_CONVERTS',
  'EVENTS_UNIT_UPGRADES','EVENTS_CITY','EVENTS_CITY_FOUNDING');
CREATE TEMP TABLE TRIClone AS SELECT * FROM "Civilizations" WHERE Type='CIVILIZATION_ROME';
UPDATE TRIClone SET "ID"=NULL,"Type"='CIVILIZATION_TRIUMPHAL_IMPERIUM',"Description"='TXT_KEY_TRI_CIV',"ShortDescription"='TXT_KEY_TRI_SHORT',"Adjective"='TXT_KEY_TRI_ADJECTIVE',"Civilopedia"='TXT_KEY_TRI_CIV_PEDIA',"CivilopediaTag"='TXT_KEY_TRI_CIV5',"Strategy"='TXT_KEY_TRI_STRATEGY',"DefaultPlayerColor"='PLAYERCOLOR_TRI_IMPERIUM',"Playable"=1,"AIPlayable"=0,"PackageID"=NULL,"DawnOfManQuote"='TXT_KEY_TRI_DAWN',"DawnOfManAudio"='',"DawnOfManImage"='TRI_Dawn.dds',"MapImage"='TRI_Map.dds',"PortraitIndex"=0,"IconAtlas"='TRI_CIV_ATLAS',"AlphaIconAtlas"='TRI_ALPHA_ATLAS';
DROP TABLE TRIClone;
CREATE TEMP TABLE TRIClone AS SELECT * FROM "Leaders" WHERE Type='LEADER_AUGUSTUS';
UPDATE TRIClone SET "ID"=NULL,"Type"='LEADER_TRI_AURELION',"Description"='TXT_KEY_TRI_LEADER',"Civilopedia"='TXT_KEY_TRI_LEADER_PEDIA',"CivilopediaTag"='TXT_KEY_TRI_AURELION',"PackageID"=NULL,"PortraitIndex"=0,"IconAtlas"='TRI_LEADER_ATLAS',"ArtDefineTag"='TRI_LeaderScene.xml';
DROP TABLE TRIClone;
CREATE TEMP TABLE TRIClone AS SELECT * FROM "Units" WHERE Type='UNIT_SWORDSMAN';
UPDATE TRIClone SET "ID"=NULL,"Type"='UNIT_TRI_UNBROKEN',"Description"='TXT_KEY_TRI_UNIT',"Civilopedia"='TXT_KEY_TRI_UNIT_PEDIA',"Help"='TXT_KEY_TRI_UNIT_HELP',"Strategy"='TXT_KEY_TRI_UNIT_STRATEGY',"IconAtlas"='TRI_OBJECT_ATLAS',"PortraitIndex"=0,"UnitFlagAtlas"='TRI_FLAG_ATLAS',"UnitFlagIconOffset"=0;
DROP TABLE TRIClone;
CREATE TEMP TABLE TRIClone AS SELECT * FROM "Buildings" WHERE Type='BUILDING_BARRACKS';
UPDATE TRIClone SET "ID"=NULL,"Type"='BUILDING_TRI_HALL_OF_TRIUMPHS',"Description"='TXT_KEY_TRI_HALL',"Civilopedia"='TXT_KEY_TRI_HALL_PEDIA',"Help"='TXT_KEY_TRI_HALL_HELP',"Strategy"='TXT_KEY_TRI_HALL_STRATEGY',"IconAtlas"='TRI_OBJECT_ATLAS',"PortraitIndex"=1;
DROP TABLE TRIClone;
